import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[] arr = new int[n];

        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        // Try to access the index that's out of bounds
        int outOfBoundsIndex = n;

        try {
            int value = arr[outOfBoundsIndex];
            System.out.println(value);
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("ArrayIndexOutOfBoundsException: Index " + outOfBoundsIndex + " out of bounds for length " + n);
        }

        sc.close();
    }
}
